-- Y'a du peuple ? — Barème des niveaux adouci (validé par Alexis le 12/11/2026)
-- Points ≈ 4 × (niveau − 1)^1,75, arrondis à 5. Niv. 10 = 185, 20 = 690, 50 = 3 630, 100 = 12 430.
-- 1) valeurs provisoires (évite les doublons temporaires sur la contrainte unique), 2) nouveau barème
update public.levels set min_points = min_points + 1000000 where level > 1;
update public.levels l set min_points = v.p
from (values (1,0),(2,5),(3,15),(4,25),(5,45),(6,65),(7,90),(8,120),(9,150),(10,185),(11,225),(12,265),(13,310),(14,355),(15,405),(16,455),(17,510),(18,570),(19,630),(20,690),(21,755),(22,825),(23,895),(24,965),(25,1040),(26,1120),(27,1195),(28,1280),(29,1365),(30,1450),(31,1540),(32,1630),(33,1720),(34,1815),(35,1915),(36,2015),(37,2115),(38,2220),(39,2325),(40,2435),(41,2545),(42,2655),(43,2770),(44,2890),(45,3005),(46,3125),(47,3250),(48,3375),(49,3500),(50,3630),(51,3760),(52,3895),(53,4030),(54,4165),(55,4305),(56,4445),(57,4585),(58,4730),(59,4875),(60,5025),(61,5175),(62,5325),(63,5480),(64,5635),(65,5795),(66,5950),(67,6115),(68,6275),(69,6440),(70,6610),(71,6775),(72,6945),(73,7120),(74,7290),(75,7470),(76,7645),(77,7825),(78,8005),(79,8190),(80,8375),(81,8560),(82,8750),(83,8940),(84,9130),(85,9325),(86,9520),(87,9715),(88,9915),(89,10115),(90,10315),(91,10520),(92,10725),(93,10930),(94,11140),(95,11350),(96,11565),(97,11775),(98,11995),(99,12210),(100,12430)) as v(n, p)
where l.level = v.n;

